   // ==================== 功能色 ====================\n    // 映射到酒馆原生功能色变量，保留语义色作为回退\n    --st-orb-primary: var(--SmartThemeQuoteColor, #667eea);\n    --st-orb-success: var(--SmartThemeSuccessColor, #28a745);\n    --st-orb-danger: var(--SmartThemeDangerColor, #dc3545);\n    --st-orb-warning: var(--SmartThemeWarningColor, #ffc107);\n    --st-orb-info: var(--SmartThemeInfoColor, #3b82f6);\n    --st-orb-secondary: var(--SmartThemeSecondaryColor, #6c757d);\n    --st-orb-accent: var(--SmartThemeQuoteColor, #667eea);\n\n    // ==================== 文本颜色 ====================\n    // 仅保留白色文字（无原生变量）\n    --st-orb-text-white: #fff;\n    --st-orb-text-contrast: var(--SmartThemeBlurTintColor, #fff);\n    --st-orb-text-on-warning: var(--SmartThemeBodyColor, #1e1e2e);\n    --st-orb-text-muted: color-mix(in srgb, var(--SmartThemeBodyColor) 60%, transparent);\n    --st-orb-text-muted-strong: color-mix(in srgb, var(--SmartThemeBodyColor) 80%, transparent);\n    --st-orb-text-danger-soft: color-mix(in srgb, var(--st-orb-danger) 60%, white);\n    --st-orb-text-success-soft: color-mix(in srgb, var(--st-orb-success) 60%, white);\n\n    // ==================== 背景色 ====================\n    // 仅保留遮罩层背景\n    --st-orb-bg-overlay: rgba(0, 0, 0, 0.6);\n    --st-orb-bg-overlay-strong: rgba(0, 0, 0, 0.65);\n    --st-orb-bg-hover: color-mix(in srgb, var(--SmartThemeBodyColor) 8%, transparent);\n    --st-orb-bg-hover-strong: color-mix(in srgb, var(--SmartThemeBodyColor) 12%, transparent);\n    --st-orb-bg-success-soft: color-mix(in srgb, var(--st-orb-success) 15%, transparent);\n    --st-orb-bg-success-subtle: color-mix(in srgb, var(--st-orb-success) 5%, transparent);\n    --st-orb-bg-danger-soft: color-mix(in srgb, var(--st-orb-danger) 15%, transparent);\n    --st-orb-bg-danger-strong: color-mix(in srgb, var(--st-orb-danger) 20%, transparent);\n    --st-orb-bg-danger-subtle: color-mix(in srgb, var(--st-orb-danger) 10%, transparent);\n    --st-orb-bg-info-soft: color-mix(in srgb, var(--st-orb-info) 15%, transparent);\n    --st-orb-bg-info-subtle: color-mix(in srgb, var(--st-orb-info) 5%, transparent);\n    --st-orb-bg-warning-soft: color-mix(in srgb, var(--st-orb-warning) 15%, transparent);\n    --st-orb-bg-surface-soft: color-mix(in srgb, var(--SmartThemeBlurTintColor) 50%, transparent);\n    --st-orb-bg-surface-strong: color-mix(in srgb, var(--SmartThemeBlurTintColor) 90%, transparent);\n    --st-orb-bg-toggle-off: color-mix(in srgb, var(--SmartThemeBodyColor) 30%, transparent);\n    --st-orb-bg-knob: var(--st-orb-text-contrast);\n\n    // ==================== 阴影（颜色相关） ====================\n    // 使用原生阴影颜色变量，提供回退值\n    --st-orb-shadow-sm: 0 2px 4px var(--SmartThemeShadowColor, rgba(0, 0, 0, 0.1));\n    --st-orb-shadow-md: 0 2px 8px var(--SmartThemeShadowColor, rgba(0, 0, 0, 0.15));\n    --st-orb-shadow-lg: 0 4px 12px var(--SmartThemeShadowColor, rgba(0, 0, 0, 0.2));\n    --st-orb-shadow-xl: 0 20px 60px var(--SmartThemeShadowColor, rgba(0, 0, 0, 0.3));\n    --st-orb-shadow-backdrop: 0 0 0 100vmax var(--st-orb-bg-overlay-strong);\n\n    // ==================== 边框色 ====================\n    --st-orb-border-soft: var(--SmartThemeBorderColor);\n    --st-orb-border-success-soft: color-mix(in srgb, var(--st-orb-success) 35%, transparent);\n    --st-orb-border-danger-soft: color-mix(in srgb, var(--st-orb-danger) 35%, transparent);\n    --st-orb-border-info-soft: color-mix(in srgb, var(--st-orb-info) 20%, transparent);\n    --st-orb-border-accent-soft: color-mix(in srgb, var(--st-orb-primary) 20%, transparent);\n\n    // ==================== 圆角 ====================\n    --st-orb-radius-sm: 4px;\n    --st-orb-radius-md: 6px;\n    --st-orb-radius-lg: 8px;\n    --st-orb-radius-xl: 12px;\n    --st-orb-radius-2xl: 16px;\n    --st-orb-radius-full: 50%;\n\n    // ==================== 间距 ====================\n    // 对齐 SillyTavern 原生 .flex-container / .inline-drawer 的 5px 基准.\n    --st-orb-spacing-2xs: 2px;\n    --st-orb-spacing-xs: 3px;\n    --st-orb-spacing-native: 5px;\n    --st-orb-spacing-sm: 5px;\n    --st-orb-spacing-md: 8px;\n    --st-orb-spacing-lg: 10px;\n    --st-orb-spacing-xl: 12px;\n    --st-orb-spacing-2xl: 16px;\n\n    // ==================== 字体大小 ====================\n    // 跟随酒馆原生 --mainFontSize, 让用户主题字号缩放能同步作用到交互 UI.\n    --st-orb-font-xs: calc(var(--mainFontSize, 15px) * 0.8);\n    --st-orb-font-sm: calc(var(--mainFontSize, 15px) * 0.9);\n    --st-orb-font-base: var(--mainFontSize, 15px);\n    --st-orb-font-md: var(--mainFontSize, 15px);\n    --st-orb-font-lg: calc(var(--mainFontSize, 15px) * 1.05);\n    --st-orb-font-xl: calc(var(--mainFontSize, 15px) * 1.1);\n    --st-orb-font-2xl: calc(var(--mainFontSize, 15px) * 1.2);\n\n    // ==================== 过渡时间 ====================\n    --st-orb-transition-fast: 0.15s;\n    --st-orb-transition-base: 0.2s;\n    --st-orb-transition-slow: 0.25s;\n\n    // ==================== Z-index ====================\n    --st-orb-z-modal: 200000;\n    --st-orb-z-popover: 200010;\n    --st-orb-z-toolbar: 199900;\n    --st-orb-z-toolbar-sub: 199890;\n    --st-orb-z-toolbar-always: 199880;\n\n    // 响应式字体和间距调整\n    @media (max-width: 480px) {\n        --st-orb-font-xs: calc(var(--mainFontSize, 15px) * 0.75);\n        --st-orb-font-sm: calc(var(--mainFontSize, 15px) * 0.85);\n        --st-orb-font-base: calc(var(--mainFontSize, 15px) * 0.95);\n        --st-orb-font-md: calc(var(--mainFontSize, 15px) * 0.95);\n        --st-orb-font-lg: var(--mainFontSize, 15px);\n        --st-orb-spacing-2xs: 2px;\n        --st-orb-spacing-xs: 3px;\n        --st-orb-spacing-native: 5px;\n        --st-orb-spacing-sm: 5px;\n        --st-orb-spacing-md: 7px;\n        --st-orb-spacing-lg: 8px;\n        --st-orb-spacing-xl: 10px;\n        --st-orb-spacing-2xl: 12px;\n    }\n}\n\n// ==================== 插件容器内的变量定义 ====================\n.st-api-manager {\n    @include st-orb-variables;\n}\n','\n@use \'../../../shared/styles/variables.scss\' as *;\n\n.api-config-list {\n  display: flex;\n  flex-direction: column;\